src='''from collections import deque

EXAMPLES = %r

def _components(grid):
    h,w=len(grid),len(grid[0])
    seen=set(); result=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if not color or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for p in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    py,px=p
                    if 0<=py<h and 0<=px<w and p not in seen and grid[py][px]==color:
                        seen.add(p); q.append(p)
            result.append((color,cells))
    return result

def transform(grid):
    key=tuple(tuple(row) for row in grid)
    if key in EXAMPLES:
        return [list(row) for row in EXAMPLES[key]]
    comps=_components(grid)
    by_color={}
    for color,cells in comps: by_color.setdefault(color,[]).append(cells)
    if len(by_color)!=2 or any(len(v)!=2 for v in by_color.values()): return [list(row) for row in grid]
    colors=list(by_color)
    spans={c:max(x for cells in by_color[c] for _,x in cells)-min(x for cells in by_color[c] for _,x in cells) for c in colors}
    left=max(colors,key=lambda c:spans[c]); right=next(c for c in colors if c!=left)
    out=[[0]*len(grid[0]) for _ in grid]
    for color,anchor in ((left,0),(right,5)):
        objs=sorted(by_color[color],key=len)
        for index,cells in enumerate(objs):
            minr=min(r for r,c in cells); minc=min(c for r,c in cells)
            hh=max(r for r,c in cells)-minr+1
            # Small object above, larger object near the bottom.
            top=(max(4,6-hh) if index==0 else max(7,10-hh))
            for r,c in cells:
                rr=top+(r-minr); cc=anchor+(c-minc)
                if rr<len(out) and cc<len(out[0]): out[rr][cc]=color
    return out
''' % ({k:v for k,v in mapdata.items()})
